/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    METSalesOrderShipmentLoadHeader shipmentLoadHeader;
    METSalesOrderShipmentLoadLines  shipmentLoadLines;
    CompanyInfo CompanyInfo;    

    ttsbegin;

    while select CompanyInfo
        where CompanyInfo.DataArea != 'DAT'
    {
        changecompany (CompanyInfo.DataArea)
        {
            while select forupdate shipmentLoadHeader
            {
                shipmentLoadHeader.ShipmentPickComplete = shipmentLoadHeader.displayPickComplete();
                shipmentLoadHeader.update();

                if (shipmentLoadHeader.ShipmentPickComplete)
                {
                    update_recordset shipmentLoadLines
                        setting PickingListComplete = true
                        where shipmentLoadLines.ShipmentId == shipmentLoadHeader.ShipmentId;
                }
            }

            info('Completed for company: ' + CompanyInfo.DataArea);
        }
    }

    ttscommit;

    info('Done');
}
